 case WM_SIZE:{int width=LOWORD(lp),height=HIWORD(lp);MoveWindow(tabs,10,8,width-20,30,TRUE);for(int id:{P_LIST,A_LIST,Q_LIST,S_LIST,R_LIST})MoveWindow(GetDlgItem(w,id),16,82,width-32,height-122,TRUE);int panelW=(width-48)/2,panelH=(height-105)/2,top=48,row2=top+panelH+16;MoveWindow(GetDlgItem(w,DASH_PAT_PANEL),16,top,panelW,panelH,TRUE);MoveWindow(GetDlgItem(w,DASH_APPT_PANEL),32+panelW,top,panelW,panelH,TRUE);MoveWindow(GetDlgItem(w,DASH_QUEUE_PANEL),16,row2,panelW,panelH,TRUE);MoveWindow(GetDlgItem(w,DASH_TYPE_PANEL),32+panelW,row2,panelW,panelH,TRUE);MoveWindow(GetDlgItem(w,DASH_PATIENTS),34,top+38,panelW-36,panelH-50,TRUE);MoveWindow(GetDlgItem(w,DASH_APPOINTMENTS),50+panelW,top+38,panelW-36,panelH-50,TRUE);MoveWindow(GetDlgItem(w,DASH_QUEUE),34,row2+38,panelW-36,panelH-50,TRUE);MoveWindow(GetDlgItem(w,DASH_TYPES),50+panelW,row2+38,panelW-36,panelH-50,TRUE);MoveWindow(statusWnd,16,height-30,width-32,22,TRUE);return 0;}
